window.LD=window.LD||{};window.LD["party/p7"]={"id":"p7","name":"The Oath of Frosthold","poss":"The Oath of Frosthold's","members":["h3","h7"],"leader":"h3","morale":88,"disposition":"wary","motto":"Measure twice. Swing once.","banner":{"c1":"#4caf50","c2":"#e8c83a","emblem":"star"},"loc":"veldrock","loc_name":"Veldrock","goal":{"text":"to see the world: 6 different places before the season ends","kind":"world","done":null,"progress":"5 of 6 places","missed":true,"crew":"The Oath of Frosthold","party":"p7"},"vows":[{"text":"to die rich","day":31,"state":"broken","ended":90,"through":false,"progress":"broken on day 30 of season 3","crew":"The Oath of Frosthold","party":"p7"}],"doing":"last seen heading home to Frosthold","progress":null,"today":["XP: Vex +32.","Coin between them: +49 silver.","Came away with a torch.","Sold 2 ore, a wolf haunch."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"little_grey_shadow","title":"Little Grey Shadow","tone":"tender","meter":"6/8","bpm":75,"diff":3,"day":53,"night":"n131","n":7,"by":null,"lead":{"id":"h7","name":"Vex","skill":0.738,"inst":"horn"}},"renown":102,"season":{"wins":5,"bosses":0,"floors":4,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":2},"career":{"wins":14,"bosses":1,"floors":9,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":8},"former":[],"fallen":[],"travel":null,"wagon":null,"pace_gap":4,"rels":[{"party":"p8","score":52},{"party":"p6","score":46}],"events":[{"id":"e60","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Duren and Vex shake on it at The Third Coat: they are now The Oath of Frosthold. (Wary, by the look of them.)","heroes":["h3","h7"],"parties":["p7"],"loc":"frosthold"},{"id":"e614","day":16,"season":1,"sday":16,"kind":"argument","imp":4,"text":"Enough is enough: Duren tells Vex exactly what Duren has been thinking for days. Nobody sleeps.","heroes":["h7","h3"],"parties":["p7"]},{"id":"e779","day":20,"season":1,"sday":20,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: The Oath of Frosthold makes it to Saltmarrow to see the sea. Something old gets set down there, and left. It was Duren's idea in the first place. XP: Duren +1080 (level 9!), Vex +960 (level 8!).","heroes":["h3","h7"],"parties":["p7"],"loc":"saltmarrow","wx":"heat","xp":{"h3":1080,"h7":960}},{"id":"e786","day":21,"season":1,"sday":21,"kind":"ambush","imp":2,"text":"On the caravan road, guarding wagons of trinkets, 2 Bandits and a Bandit Captain get in the Oath of Frosthold's way, briefly. That Steam Burst from Duren was the moment it tipped. Ask the others what won it: Vex's Tailwind. Loot: 41 silver each, 5 stolen goods, 2 rations.","heroes":["h3","h7"],"parties":["p7"],"loc":"kingsroad","fight":"f54","foes":["bandit_captain","bandit","bandit"],"where":"on the caravan road, guarding wagons of trinkets","won":true,"close":false,"shape":"place","reworded":-12,"wx":"rain"},{"id":"e788","day":21,"season":1,"sday":21,"kind":"caravan","imp":3,"text":"CARAVAN SAVED: the merchants hired The Oath of Frosthold to guard trinkets into Saltmarrow. Bandits tried it. The merchants paid 74 silver and a bonus in sausages.","heroes":["h3","h7"],"parties":["p7"],"loc":"saltmarrow","wx":"heat"},{"id":"e893","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Duren sells two jugs of camp-brewed ale to the Veldrock landlord, who drinks a cup and orders a third. Duren puts it down to Brewer.","heroes":["h3"],"parties":["p7"],"loc":"veldrock","skill":"brewer"},{"id":"e940","day":24,"season":1,"sday":24,"kind":"campfire","imp":1,"text":"Vex brings back a brace of rabbits for the pot. Duren cooks them. Teamwork.","heroes":["h7","h3"],"parties":["p7"],"loc":"veldrock"},{"id":"e944","day":25,"season":1,"sday":25,"kind":"road","imp":3,"text":"A pedlar on the road to Frosthold has a bone flute with a split in it. Vex binds the crack with waxed thread, and the flute plays again. The pedlar presses it into her hands.","heroes":["h7","h3"],"parties":["p7"],"road":"frosthold~veldrock","road_rec":"r218"},{"id":"e969","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"A Frosthold locksmith asks Duren to stop testing locks by melting them.","heroes":["h3"],"parties":["p7"],"loc":"frosthold","skill":"burn_it_and_see"},{"id":"e992","day":26,"season":1,"sday":26,"kind":"road","imp":2,"text":"Vex lifts a boulder for the Whitepeak Cairn and drops it on a foot, and the cairn is forgiven, but only just.","heroes":["h7","h3"],"parties":["p7"],"road":"frosthold~whitepeak","road_rec":"r229"},{"id":"e1013","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Vex carries Duren's pack the last mile back to camp and says it was no trouble. It was some trouble.","heroes":["h7","h3"],"parties":["p7"],"loc":"whitepeak","skill":"heavy_lifter"},{"id":"e1026","day":27,"season":1,"sday":27,"kind":"road","imp":3,"text":"Snaggle blocks Duren's way with a rope and a wooden sign that reads TOL. Duren pays one copper and is given a receipt made of bark.","heroes":["h3","h7"],"parties":["p7"],"road":"frostspire~whitepeak","traveller":"muddy_boot","road_rec":"r232"},{"id":"e1044","day":27,"season":1,"sday":27,"kind":"tarot","imp":2,"text":"The Oath of Frosthold sit in a ring while Vex turns the Pressed-Leaf Tarot for all of them before Frostspire: the Sun upside down, the Wheel of Fortune and Judgement. Vex says it could go either way.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","reading":"r234"},{"id":"e1067","day":28,"season":1,"sday":28,"kind":"delve","imp":1,"text":"The Oath of Frosthold descends into Frostspire, untouched (0%).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire"},{"id":"e1068","day":28,"season":1,"sday":28,"kind":"trap","imp":2,"text":"Duren springs thin ice over a drop in the icicle porch on the first floor of Frostspire (cracked collarbone).","heroes":["h3"],"parties":["p7"],"loc":"frostspire"},{"id":"e1069","day":28,"season":1,"sday":28,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold gives the first floor of Frostspire another day, slowly, chalking every door, and two rooms give way (the cairn of the turned-back, the icicle porch).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1084","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Duren has no eyebrows again. He says it was worth it, and won't explain. Duren puts it down to Burn It and See.","heroes":["h3"],"parties":["p7"],"loc":"frostspire","skill":"burn_it_and_see"},{"id":"e1088","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"Chalk marks on two rooms of the first floor of Frostspire say The Oath of Frosthold has been through, without hurrying (the wrecked sledge, the scribe's alcove).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1153","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"A long day on the first floor of Frostspire. The Oath of Frosthold comes through two rooms, with a look round every corner: the yeti's nest of shinies, the wind-scoured foot.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1154","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"The Oath of Frosthold comes out into the light after 3 days with the dark still in every seam. They turned up the cairn of the turned-back and the yeti's nest of shinies, got down to the first floor, took 6 rooms off the map's blank side, split 82 silver on the way up and turned back because they were down to the last torch.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","days":3,"bottom":false,"rooms":["the cairn of the turned-back","the yeti's nest of shinies"],"gold":82,"turn":"dark"},{"id":"e1169","day":30,"season":1,"sday":30,"kind":"argument","imp":2,"text":"Vex and Duren are not speaking. It's about who ate the last of the cheese. It's never really about who ate the last of the cheese.","heroes":["h7","h3"],"parties":["p7"]},{"id":"e1244","day":31,"season":2,"sday":1,"kind":"campfire","imp":3,"text":"A month in The Oath of Frosthold together. Duren and Vex know each other's snores, sorrows and orders by heart.","heroes":["h3","h7"],"parties":["p7"],"loc":"veldrock"},{"id":"e1253","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Oath of Frosthold stands before the league and swears it: to die rich. The Annals are watching.","heroes":["h3","h7"],"parties":["p7"]},{"id":"e1333","day":34,"season":2,"sday":4,"kind":"road","imp":3,"text":"Vex and Duren are waved into a shepherds' midsummer gathering on a hilltop: a roast lamb, a fire, a fiddle. There is dancing, and the sheep join in.","heroes":["h7","h3"],"parties":["p7"],"road":"frosthold~veldrock","road_rec":"r286"},{"id":"e1412","day":36,"season":2,"sday":6,"kind":"talent","imp":2,"text":"Duren swallows a torch at the Ironhaven tavern and breathes it out in the shape of a dragon. The house pays. The words of Fire Eater, half under his breath.","heroes":["h3"],"parties":["p7"],"loc":"ironhaven","skill":"fire_eater"},{"id":"e1419","day":36,"season":2,"sday":6,"kind":"argument","imp":2,"text":"Duren and Vex spend supper disagreeing about whether the party's name was a mistake, politely at first.","heroes":["h3","h7"],"parties":["p7"]},{"id":"e1446","day":37,"season":2,"sday":7,"kind":"sniped","imp":3,"text":"Mother Thornmere was killed by The Sunlit Almanac today, and The Vigil of Carrbridge and The Oath of Frosthold all hear it from the same tired messenger. Their trips are rethought on the spot.","heroes":["h1","h10","h18","h19","h20","h3","h7","h8"],"parties":["p2","p4","p7"],"loc":"thornmere_ruins","snipers":["h8","h20","h18","h19"],"where":"many","boss":"Mother Thornmere","in_fight":"f91"},{"id":"e1483","day":38,"season":2,"sday":8,"kind":"night_game","imp":2,"text":"The bandit blocks the way on the road to Thornwall with a weapon in one hand and a request in the other: one game of Crooked Cards, and nobody gets hurt. Duren loses, and the bandit holds out both hands for 2 lots of remains, which the crew drops in with a sigh. Vex keeps a hand on the pack for the next mile, and a wary eye on the ditches.","heroes":["h3","h7"],"parties":["p7"],"loc":"thornwall","night":"n94","monster_game":"bandit"},{"id":"e1592","day":40,"season":2,"sday":10,"kind":"tarot","imp":2,"text":"On the last night before the Wolf Den, Vex spreads a cloak by the fire and reads the Pressed-Leaf Tarot for the whole of The Oath of Frosthold: the Six of Cups, the Page of Swords and Temperance. Vex smiles at the last card.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","reading":"r326"},{"id":"e1598","day":40,"season":2,"sday":10,"kind":"argument","imp":1,"text":"The Oath of Frosthold spends the evening listening to Vex and Duren argue about whose idea the last dungeon was.","heroes":["h7","h3"],"parties":["p7"]},{"id":"e1604","day":41,"season":2,"sday":11,"kind":"delve","imp":1,"text":"The Oath of Frosthold descends into the Wolf Den, untouched (0%).","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den"},{"id":"e1605","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"Down in the Wolf Den, The Oath of Frosthold maps three rooms of the first floor, steadily (the bone yard, the stream crossing, the fallen trunk).","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1638","day":41,"season":2,"sday":11,"kind":"gift","imp":2,"text":"Vex gives Duren a Bone Flute. \"For luck,\" Vex says, and won't explain further.","heroes":["h7","h3"],"parties":["p7"],"loc":"wolf_den"},{"id":"e1654","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"The Oath of Frosthold's plan for the season, as told to the barkeep: to earn 300 silver between them before the season ends.","heroes":["h3","h7"],"parties":["p7"]},{"id":"e1682","day":42,"season":2,"sday":12,"kind":"delve_day","imp":1,"text":"Torch by torch through the first floor of the Wolf Den, The Oath of Frosthold makes it through two rooms, at a steady pace: a hidden room behind the fallen trunk, the wolf lane.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e1688","day":42,"season":2,"sday":12,"kind":"talent","imp":1,"text":"Duren lights the campfire by breathing on it. Vex has seen this forty times and still claps. Fire Eater, cast gently, for once.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","skill":"fire_eater"},{"id":"e1699","day":43,"season":2,"sday":13,"kind":"fight","imp":1,"text":"Duren takes the worst of it as the Oath of Frosthold beats 3 Dire Wolves in the family hollow on the first floor of the Wolf Den. Duren's Firebolt was where the fight changed hands. Loot: 4 pelts, 4 fangs & claws, 6 wolf haunches.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","fight":"f98","foes":["dire_wolf","dire_wolf","dire_wolf"],"where":"in the family hollow on the first floor of the Wolf Den","won":true,"close":false,"shape":"hero","reworded":-31,"wx":"rain"},{"id":"e1700","day":43,"season":2,"sday":13,"kind":"delve_day","imp":1,"text":"Deeper into the first floor of the Wolf Den: The Oath of Frosthold sees two rooms today, at a cautious pace (the elders' crossing, the carcass store).","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1719","day":43,"season":2,"sday":13,"kind":"talent","imp":1,"text":"Vex tries out a new verse on the party. Duren suggests a rhyme. It's in the song now. (Packs the House, if anyone's asking.)","heroes":["h7","h3"],"parties":["p7"],"loc":"wolf_den","skill":"packs_the_house","wx":"rain"},{"id":"e1746","day":44,"season":2,"sday":14,"kind":"wild_room","imp":3,"text":"Vex accompanied the pack of the Wolf Den at its moon-howl, and the wolves have asked for an encore. Several are said to be taking lessons.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","room":"wild_moon_chorus","wx":"rain"},{"id":"e1747","day":44,"season":2,"sday":14,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold keeps at the first floor of the Wolf Den one door at a time, two rooms deep in the day: the moon-howl hollow, Old Snapjaw.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_moon_chorus"]},"wx":"rain"},{"id":"e1758","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"Duren buries flat stones under the coals and lays the bedrolls over them. Vex sleeps like a cat on a hearth. The pyromancer's trade has a name for that: Ember Bed.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","skill":"ember_bed","wx":"rain"},{"id":"e1759","day":44,"season":2,"sday":14,"kind":"campfire","imp":3,"text":"Vex and Duren share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h7","h3"],"parties":["p7"],"loc":"wolf_den","wx":"rain"},{"id":"e1767","day":45,"season":2,"sday":15,"kind":"fight","imp":2,"text":"In the whelping hollow on the first floor of the Wolf Den, 3 Dire Wolves and a Wolf get in the Oath of Frosthold's way, briefly. The wolf went down to Duren's Steam Burst. Loot: 8 pelts, 4 wolf haunches, 3 fangs & claws.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","fight":"f99","foes":["dire_wolf","wolf","dire_wolf"],"where":"in the whelping hollow on the first floor of the Wolf Den","won":true,"close":false,"shape":"place","reworded":-3,"wx":"rain"},{"id":"e1768","day":45,"season":2,"sday":15,"kind":"delve_day","imp":1,"text":"The map of the Wolf Den grows by two rooms of the first floor, walked without hurrying by The Oath of Frosthold: the whelping hollow, the mud wallow.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1798","day":46,"season":2,"sday":16,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold tallies up the first floor of the Wolf Den at nightfall: two rooms, taken steadily, and the names go in the book (the hunter's old trap line, the underground stream).","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1799","day":46,"season":2,"sday":16,"kind":"night","imp":2,"text":"An old pilgrim stops at The Oath of Frosthold's camp on the first floor of the Wolf Den and swears there's treasure left in Goblin Camp. Everyone pretends not to be interested.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","wx":"rain"},{"id":"e1825","day":47,"season":2,"sday":17,"kind":"wild_room","imp":3,"text":"Vex carved a Roast Boar haunch in the Wolf Den three ways for the wolves and kept the best bit for her crew. The wolves have called it a fair cut.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","room":"wild_roast_boar_haunch","wx":"fog"},{"id":"e1826","day":47,"season":2,"sday":17,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold pushes on through the first floor of the Wolf Den slowly, chalking every door. Two rooms by nightfall: the hollow of eyes, the guarded haunch.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_roast_boar_haunch"]},"wx":"fog"},{"id":"e1827","day":47,"season":2,"sday":17,"kind":"night","imp":2,"text":"Something small and clever gets into The Oath of Frosthold's camp on the first floor of the Wolf Den overnight. Vex wakes up 5 silver and 2 rations lighter.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","wx":"fog"},{"id":"e1845","day":48,"season":2,"sday":18,"kind":"boss","imp":5,"text":"The Oath of Frosthold brings down Old Grizzlemaw's Widow and a Wolf at the bottom of the Wolf Den and lives to tell of it. The last wolf is gone before anyone can stop it. Vex's Off-Key Note landed on it at the right moment. The others will say it was close. Duren made sure it wasn't. Loot: 4 pelts, 6 fangs & claws, Grizzlemaw's honeycomb.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","fight":"f106","foes":["cave_bear","wolf"],"where":"at the bottom of The Wolf Den","won":true,"close":false,"shape":"plain","reworded":-38,"wx":"fog"},{"id":"e1846","day":48,"season":2,"sday":18,"kind":"treasure","imp":2,"text":"Old Grizzlemaw's Widow had been saving. The savings come to 8 gold pieces, and are now somebody else's.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","in_fight":"f106","wx":"fog"},{"id":"e1847","day":48,"season":2,"sday":18,"kind":"gear","imp":1,"text":"In the old bear's winter chamber on the first floor of the Wolf Den, Duren finds a Keen Oilskin Cloak and puts it on. Keen: a steadier aim (+2 aim).","heroes":["h3"],"parties":["p7"],"loc":"wolf_den","wx":"fog"},{"id":"e1848","day":48,"season":2,"sday":18,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold works the first floor of the Wolf Den at a steady pace: two rooms (the moss spring, the old bear's winter chamber).","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1849","day":48,"season":2,"sday":18,"kind":"delve_done","imp":3,"text":"After 8 days underground, The Oath of Frosthold climbs back into the open air, gulping it down like water. They went as deep as the place goes, turned up a hidden room behind the fallen trunk, Old Snapjaw and the old bear's winter chamber, put 100% of it on paper, took 17 rooms off the map's blank side and came away with 193 silver between them. The Wolf Den is mostly explored (80%) now, with the league's pencil marks all over it.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den","days":8,"bottom":true,"rooms":["a hidden room behind the fallen trunk","Old Snapjaw"],"gold":193,"turn":"done","wx":"fog"},{"id":"e1850","day":48,"season":2,"sday":18,"kind":"talent","imp":1,"text":"Vex bakes flatbread on a hot stone. It's the first bread the crew has had in a week. Nobody speaks while eating. Somebody asks how. 'Trail Baker,' says Vex.","heroes":["h7"],"parties":["p7"],"loc":"wolf_den","skill":"trail_baker","wx":"fog"},{"id":"e1871","day":48,"season":2,"sday":18,"kind":"goal_progress","imp":2,"text":"The Oath of Frosthold is getting close: earn 300 silver between them before the season ends (198 of 300 silver).","heroes":["h3","h7"],"parties":["p7"]},{"id":"e1873","day":48,"season":2,"sday":18,"kind":"big_move","imp":3,"text":"The Oath of Frosthold brings down Old Grizzlemaw's Widow and a Wolf at the bottom of the Wolf Den and lives to tell of it. On the table: The Oath of Frosthold +86 party renown (6th to 3rd among the crews).","heroes":["h3","h7"],"parties":["p7"],"party_moves":[{"party":"p7","gain":86,"from":6,"to":3}],"cause":"e1845","fight":"f106"},{"id":"e1893","day":49,"season":2,"sday":19,"kind":"party_life","imp":1,"text":"Duren arrives at camp an hour behind Vex and finds the good spot by the fire taken.","heroes":["h3","h7"],"parties":["p7"],"loc":"wolf_den"},{"id":"e1900","day":49,"season":2,"sday":19,"kind":"gift","imp":2,"text":"By the fire, Vex quietly hands Duren a Clay Figurine of Somebody Else. Duren pockets it like it's treasure.","heroes":["h7","h3"],"parties":["p7"],"loc":"hollowood"},{"id":"e1903","day":49,"season":2,"sday":19,"kind":"ability","imp":2,"text":"Word gets round Hollowood that Vex is playing tonight. They're standing on the tables by nine. 26 silver in tips, and Duren gets free drinks for being with the band.","heroes":["h7","h3"],"parties":["p7"],"loc":"hollowood","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e1914","day":49,"season":2,"sday":19,"kind":"goal_done","imp":4,"text":"GOAL: The Oath of Frosthold set out to earn 300 silver between them before the season ends, and they have done it, with 11 days to spare. It was Vex's idea in the first place. XP: Duren +919 (level 14!), Vex +800 (level 13!).","heroes":["h3","h7"],"parties":["p7"],"xp":{"h3":919,"h7":800}},{"id":"e1951","day":51,"season":2,"sday":21,"kind":"fight","imp":1,"text":"It's 2 Walking Toadstools against the Oath of Frosthold in the Greenwood, and it isn't close. It was even until Duren's Immolate. Then it wasn't. Loot: 1 herb, a walking-cap.","heroes":["h3","h7"],"parties":["p7"],"loc":"greenwood","fight":"f114","foes":["walking_toadstool","walking_toadstool"],"where":"in The Greenwood","won":true,"close":false,"shape":"foe","reworded":-22,"wx":"rain"},{"id":"e1974","day":51,"season":2,"sday":21,"kind":"meet","imp":2,"text":"The Oath of Frosthold and Verdant Edge share a fire in the Greenwood and trade news.","heroes":["h3","h7","h12","h17"],"parties":["p7","p8"],"loc":"greenwood","wx":"rain"},{"id":"e1981","day":51,"season":2,"sday":21,"kind":"talent","imp":1,"text":"Duren builds the campfire twice the size it needs to be, on principle. Travellers on the far ridge wave. A small Bonfire Night, cast without looking up.","heroes":["h3"],"parties":["p7"],"loc":"greenwood","skill":"bonfire_night","wx":"rain"},{"id":"e1989","day":52,"season":2,"sday":22,"kind":"hunt","imp":4,"text":"The Greenwood: At first light Vex stops, hand raised. Among the oaks runs a line of pale prints, each one clean and faintly silver, and a sapling scored high up by antlers like a winter tree. The great white stag has walked here, unhurried.","heroes":["h7","h3"],"parties":["p7"],"loc":"greenwood","road_rec":"r414"},{"id":"e1990","day":52,"season":2,"sday":22,"kind":"hunt","imp":4,"text":"The Greenwood: The great white stag, the one the old keepers say leads hunters to wonders. Vex stands in the hush with it for the span of three breaths, and the bow stays unstrung.","heroes":["h7","h3"],"parties":["p7"],"loc":"greenwood","road_rec":"r416"},{"id":"e2005","day":52,"season":2,"sday":22,"kind":"map_shared","imp":1,"text":"Maps change hands in the Greenwood: Verdant Edge gives The Oath of Frosthold a copy of what they know of the Collapsed Mine, as far as the first floor.","heroes":["h12","h17","h3","h7"],"parties":["p8","p7"],"loc":"greenwood","dungeon":"collapsed_mine","price":0},{"id":"e2006","day":52,"season":2,"sday":22,"kind":"gift","imp":2,"text":"Duren admired Vex's Wooden Duck on Wheels one too many times. Now it's Duren's.","heroes":["h7","h3"],"parties":["p7"],"loc":"greenwood"},{"id":"e2014","day":53,"season":2,"sday":23,"kind":"hunt","imp":2,"text":"The Greenwood: Vex takes half of the berries and leaves half for whatever comes next, the way the old hunters always did.","heroes":["h7","h3"],"parties":["p7"],"loc":"greenwood","road_rec":"r422"},{"id":"e2015","day":53,"season":2,"sday":23,"kind":"night","imp":2,"text":"Duren follows strange lights away from the camp in the Greenwood, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h3","h7"],"parties":["p7"],"loc":"greenwood"},{"id":"e2028","day":53,"season":2,"sday":23,"kind":"music","imp":3,"text":"The Oath of Frosthold have an anthem now. It was \"Little Grey Shadow\", sung round the fire until the stars seemed to know the words.","heroes":["h3","h7"],"parties":["p7"],"loc":"greenwood","anthem":"little_grey_shadow","night":"n131"},{"id":"e2031","day":53,"season":2,"sday":23,"kind":"campfire","imp":1,"text":"Vex gives Duren the crust end of the loaf, which in some families is a declaration.","heroes":["h7","h3"],"parties":["p7"],"loc":"greenwood"},{"id":"e2068","day":54,"season":2,"sday":24,"kind":"ability","imp":2,"text":"A Thornwall landlord books Vex for one song and gets nine. 50 silver, a free supper, and a queue of people wanting the words written down.","heroes":["h7"],"parties":["p7"],"loc":"thornwall","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e2082","day":55,"season":2,"sday":25,"kind":"contract","imp":2,"text":"A man in Thornwall who doesn't give his name pays The Oath of Frosthold to move three sacks of what are definitely not stolen candlesticks to Ashfen. Half now, half on arrival, no questions.","heroes":["h3","h7"],"parties":["p7"],"loc":"thornwall"},{"id":"e2083","day":55,"season":2,"sday":25,"kind":"escort","imp":1,"text":"The Oath of Frosthold ties down three sacks of what are definitely not stolen candlesticks with borrowed rope, checks it twice, and sets off from Thornwall for Carrbridge before midday.","heroes":["h3","h7"],"parties":["p7"],"loc":"thornwall"},{"id":"e2084","day":55,"season":2,"sday":25,"kind":"road","imp":2,"text":"Marigold swings the great pot off her back for Duren for the first time and says everyone should be fed, adventurers especially.","heroes":["h3","h7"],"parties":["p7"],"road":"carrbridge~thornwall","traveller":"marigold","road_rec":"r433"},{"id":"e2107","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"A Carrbridge street crowd learns the chorus to Vex's newest song in one go. Packs the House, the guild calls it.","heroes":["h7"],"parties":["p7"],"loc":"carrbridge","skill":"packs_the_house"},{"id":"e2137","day":56,"season":2,"sday":26,"kind":"campfire","imp":1,"text":"Duren and Vex reach a truce over the good blanket: alternate nights, strictly kept, frequently cheated.","heroes":["h3","h7"],"parties":["p7"],"loc":"carrbridge"},{"id":"e2158","day":57,"season":2,"sday":27,"kind":"contract","imp":2,"text":"A back door in Ashfen, a knock, a purse: The Oath of Frosthold delivers three sacks of what are definitely not stolen candlesticks and collects 74 each. The less said the better.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashfen"},{"id":"e2176","day":57,"season":2,"sday":27,"kind":"gift","imp":2,"text":"\"For the time you pulled me out,\" says Duren, and gives Vex an Old Guild Signet. Vex pretends not to be moved.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashfen"},{"id":"e2213","day":58,"season":2,"sday":28,"kind":"map_shared","imp":1,"text":"Verdant Edge lets The Oath of Frosthold copy the map of the Ashveil Crypts by the fire, every room as far as the first floor. It takes half the night and most of a candle.","heroes":["h12","h17","h3","h7"],"parties":["p8","p7"],"loc":"ashveil_crypts","dungeon":"ashveil_crypts","price":0,"wx":"fog"},{"id":"e2214","day":58,"season":2,"sday":28,"kind":"meet","imp":1,"text":"The Oath of Frosthold and Verdant Edge share a fire outside the Ashveil Crypts. Nobody draws steel, which counts as a good meeting these days.","heroes":["h3","h7","h12","h17"],"parties":["p7","p8"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2218","day":58,"season":2,"sday":28,"kind":"talent","imp":1,"text":"Duren singes a cobweb, then the cobweb behind it, then the one that was holding up a net.","heroes":["h3"],"parties":["p7"],"loc":"ashveil_crypts","skill":"burn_it_and_see","wx":"fog"},{"id":"e2250","day":59,"season":2,"sday":29,"kind":"delve","imp":1,"text":"The Oath of Frosthold descends into the Ashveil Crypts, barely touched (6%).","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2251","day":59,"season":2,"sday":29,"kind":"fight","imp":1,"text":"With Duren hitting hardest, the Oath of Frosthold sees off 2 Giant Rats and a Skeleton in the gravediggers' shed on the first floor of the Ashveil Crypts. Somewhere around Duren's Steam Burst, the other side stopped believing. Loot: 1 fang, a rat haunch, 4 bones.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","fight":"f132","foes":["giant_rat","giant_rat","skeleton"],"where":"in the gravediggers' shed on the first floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-28,"wx":"fog"},{"id":"e2252","day":59,"season":2,"sday":29,"kind":"gear","imp":1,"text":"In a walled-up room beside the gravediggers' shed on the first floor of the Ashveil Crypts, Vex finds a Keen Steel Spade, and stashes it to sell. Keen: a steadier aim (+2 aim).","heroes":["h7"],"parties":["p7"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2253","day":59,"season":2,"sday":29,"kind":"delve_day","imp":1,"text":"The gravediggers' shed, a walled-up room beside the gravediggers' shed: the day's work on the first floor of the Ashveil Crypts for The Oath of Frosthold, taken without hurrying.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":1,"wild":[]},"wx":"fog"},{"id":"e2268","day":60,"season":2,"sday":30,"kind":"gear","imp":1,"text":"In the gatekeeper's lodge on the first floor of the Ashveil Crypts, Duren finds Delver's Brass Lantern, and stashes it to sell. Delver's: harder to ambush (+8%).","heroes":["h3"],"parties":["p7"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2269","day":60,"season":2,"sday":30,"kind":"fight","imp":1,"text":"In the bier hall on the first floor of the Ashveil Crypts, the Oath of Frosthold squares up to 2 Skeleton Archers and carries the day. Vex's Marching Song had everyone hitting harder. Loot: 5 bones, 2 crypt-caps.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","fight":"f133","foes":["skeleton_archer","skeleton_archer"],"where":"in the bier hall on the first floor of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-29,"wx":"fog"},{"id":"e2270","day":60,"season":2,"sday":30,"kind":"delve_day","imp":1,"text":"Another day under the Ashveil Crypts: The Oath of Frosthold walks three rooms of the first floor, at full stretch (the gatekeeper's lodge, the bier hall, the grave-goods store).","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2293","day":60,"season":2,"sday":30,"kind":"delve_done","imp":3,"text":"The Oath of Frosthold climbs the last ladder after 2 days, and the sitting down happens at the top of it. They worked through 5 rooms, got down to the first floor, mapped 28% of it, found a walled-up room beside the gravediggers' shed and the gatekeeper's lodge and split 109 silver on the way up. Counting every crew that has been down, the Ashveil Crypts is mostly unexplored (17%).","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","days":2,"bottom":false,"rooms":["a walled-up room beside the gravediggers' shed","the gatekeeper's lodge"],"gold":109,"wx":"fog"},{"id":"e2294","day":60,"season":2,"sday":30,"kind":"night","imp":2,"text":"A carter with a broken wheel outside the Ashveil Crypts pays for The Oath of Frosthold's help in gossip: the deep rooms of Goblin Camp are open again.","heroes":["h3","h7"],"parties":["p7"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2330","day":61,"season":3,"sday":1,"kind":"road","imp":4,"text":"The Muddy Boot Pack petition Duren to join the band as 'Pointy Division'. Duren politely declines. They take it well and ask if he can borrow a boot.","heroes":["h3","h7"],"parties":["p7"],"road":"frosthold~whitepeak","traveller":"muddy_boot","road_rec":"r488"},{"id":"e2390","day":62,"season":3,"sday":2,"kind":"fight","imp":1,"text":"The Oath of Frosthold dispatches a Frost Imp in Whitepeak Pass, in the middle of a storm. Duren had the last word, and the word was Firebolt.","heroes":["h3","h7"],"parties":["p7"],"loc":"whitepeak","fight":"f136","foes":["frost_imp"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"weather","reworded":-26,"wx":"storm"},{"id":"e2421","day":63,"season":3,"sday":3,"kind":"campfire","imp":1,"text":"Duren trims Vex's hair at the campfire with a borrowed knife. The result is described as brave.","heroes":["h7","h3"],"parties":["p7"],"loc":"whitepeak","wx":"storm"},{"id":"e2479","day":65,"season":3,"sday":5,"kind":"gift","imp":2,"text":"\"For the time you pulled me out,\" says Vex, and gives Duren a Garnet Ring. Duren pretends not to be moved.","heroes":["h7","h3"],"parties":["p7"],"loc":"frosthold","wx":"storm"},{"id":"e2480","day":65,"season":3,"sday":5,"kind":"talent","imp":2,"text":"Vex sings the whole way to keep the pace. Nobody admits it works. Vex puts it down to Packs the House.","heroes":["h7"],"parties":["p7"],"loc":"frosthold","skill":"packs_the_house","wx":"storm"},{"id":"e2483","day":65,"season":3,"sday":5,"kind":"campfire","imp":2,"text":"Duren and Vex invent a scoring system for snoring. Nobody else is consulted.","heroes":["h3","h7"],"parties":["p7"],"loc":"frosthold","wx":"storm"},{"id":"e2508","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Vex talks two angry farmers out of a fight at the Veldrock tavern, and both buy Vex a drink.","heroes":["h7"],"parties":["p7"],"loc":"veldrock","skill":"peacemaker"},{"id":"e2513","day":66,"season":3,"sday":6,"kind":"ability","imp":2,"text":"Vex plays a Veldrock tavern so packed the landlord opens the windows so the street can hear. 54 silver, a lot of new fans and a very happy party.","heroes":["h7"],"parties":["p7"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e2521","day":66,"season":3,"sday":6,"kind":"argument","imp":1,"text":"Vex and Duren spend supper disagreeing about who ate the last of the cheese, politely at first.","heroes":["h7","h3"],"parties":["p7"]},{"id":"e2577","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Duren plays a slow tune on the bone flute at Frosthold and the room goes quiet. It's the surprise note that does it.","heroes":["h3"],"parties":["p7"],"loc":"frosthold"},{"id":"e2612","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"Duren sets fire to a scarecrow because it 'looked shifty'. A crow thanks him. (Burn It and See, if anyone's asking.)","heroes":["h3"],"parties":["p7"],"loc":"whitepeak","skill":"burn_it_and_see"},{"id":"e2651","day":70,"season":3,"sday":10,"kind":"tarot","imp":2,"text":"Vex lays three cards on a flat stone for The Oath of Frosthold, with Frostspire a short walk off in the dark: the Queen of Pentacles, the Three of Swords and the Emperor. Vex says it could go either way.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","reading":"r559"},{"id":"e2665","day":71,"season":3,"sday":11,"kind":"delve","imp":1,"text":"The Oath of Frosthold descends into Frostspire, mostly unexplored (27%).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire"},{"id":"e2666","day":71,"season":3,"sday":11,"kind":"fight","imp":3,"text":"It's 2 Yetis against the Oath of Frosthold in the icicle porch on the first floor of Frostspire, and it isn't close. The last yeti doesn't stay to see the end. Duren's Frost Shard slowed the yeti to a crawl. Ask the others what won it: Vex's Marching Song. Loot: 7 pelts.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","fight":"f160","foes":["yeti","yeti"],"where":"in the icicle porch on the first floor of Frostspire","won":true,"close":false,"shape":"foe","reworded":-44},{"id":"e2668","day":71,"season":3,"sday":11,"kind":"fight","imp":1,"text":"The Oath of Frosthold sees off a Frost Wolf and an Ice Wraith in the wrecked sledge on the first floor of Frostspire without much fuss. Vex's Off-Key Note landed on the frost wolf at the right moment. Loot: 3 pelts, 3 ectoplasm, 1 frost crystal.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","fight":"f161","foes":["frost_wolf","ice_wraith"],"where":"in the wrecked sledge on the first floor of Frostspire","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e2669","day":71,"season":3,"sday":11,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold works the first floor of Frostspire carefully: three rooms (the icicle porch, the wrecked sledge, the ice gate).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"cautious","stats":{"rooms":3,"empty":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2703","day":71,"season":3,"sday":11,"kind":"goal","imp":1,"text":"After a long night's talk, The Oath of Frosthold settles on a goal: to see the world: 6 different places before the season ends.","heroes":["h3","h7"],"parties":["p7"]},{"id":"e2710","day":72,"season":3,"sday":12,"kind":"delve_day","imp":1,"text":"A long day on the first floor of Frostspire. The Oath of Frosthold comes through five rooms, one door at a time: the frozen guardroom, the yeti's larder, the sentries' bunks and 2 more.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"steady","stats":{"rooms":5,"empty":5,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2711","day":72,"season":3,"sday":12,"kind":"night","imp":3,"text":"Something small and clever gets into The Oath of Frosthold's camp on the first floor of Frostspire overnight. Vex wakes up 6 silver and 2 rations lighter.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire"},{"id":"e2766","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"By lamplight on the first floor of Frostspire, The Oath of Frosthold clears the way through five rooms, slowly, chalking every door: the white chapel, a slope of packed snow that winds up the inside of the tower, the sentry stair and 2 more.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"cautious","stats":{"rooms":5,"empty":5,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2800","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"The map of Frostspire grows by three rooms of the first floor, walked with a look round every corner by The Oath of Frosthold: the lens hall, the ice-locked armoury, the yeti's meat hall.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"cautious","stats":{"rooms":3,"empty":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e2829","day":74,"season":3,"sday":14,"kind":"campfire","imp":2,"text":"Vex orders Duren a mystery stew before Duren even sits down. Remembering an order is how it starts.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire"},{"id":"e2843","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"The Oath of Frosthold spends the day on the second floor of Frostspire, steadily, and covers two rooms: the windbreak, the yeti's nest of shinies.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2844","day":75,"season":3,"sday":15,"kind":"night","imp":1,"text":"A hooded stranger shares The Oath of Frosthold's fire on the second floor of Frostspire, eats half the stew, and says something very specific about the Collapsed Mine before leaving.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire"},{"id":"e2890","day":76,"season":3,"sday":16,"kind":"fight","imp":1,"text":"Riding a good week, the Oath of Frosthold beats a Yeti in the yeti's empty pot on the second floor of Frostspire. The yeti spent the rest of the fight on fire, courtesy of Duren's Firebolt. Vex's Marching Song kicked in when it counted. Loot: 7 pelts, 3 yeti steaks.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","fight":"f166","foes":["yeti"],"where":"in the yeti's empty pot on the second floor of Frostspire","won":true,"close":false,"shape":"mood","reworded":-20,"wx":"snow"},{"id":"e2891","day":76,"season":3,"sday":16,"kind":"delve_day","imp":1,"text":"Torch by torch through the second floor of Frostspire, The Oath of Frosthold makes it through one room, without hurrying: the yeti's empty pot.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"snow"},{"id":"e2892","day":76,"season":3,"sday":16,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 6 days, and The Oath of Frosthold comes out into it shading every eye. They got down to the second floor, cleared 6 rooms, came across the ice-locked armoury and the yeti's empty pot, mapped 28% of it, split 138 silver on the way up and turned back because they were down to the last torch. Pin it to the board: Frostspire is mostly unexplored (32%).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","days":6,"bottom":false,"rooms":["the ice-locked armoury","the yeti's empty pot"],"gold":138,"turn":"dark","wx":"snow"},{"id":"e2954","day":78,"season":3,"sday":18,"kind":"talent","imp":2,"text":"Vex plays two encores at the Frosthold tavern and the landlord pays her to stop so the place can close.","heroes":["h7"],"parties":["p7"],"loc":"frosthold","skill":"packs_the_house","wx":"snow"},{"id":"e2992","day":79,"season":3,"sday":19,"kind":"night","imp":2,"text":"A soldier with old wounds sits at The Oath of Frosthold's fire in Whitepeak Pass and talks about the Collapsed Mine until the fire is ash. He was there once. He won't say when.","heroes":["h3","h7"],"parties":["p7"],"loc":"whitepeak","wx":"snow"},{"id":"e3002","day":79,"season":3,"sday":19,"kind":"talent","imp":1,"text":"Duren pours a capful of homebrew for Vex at a rest stop. Vex coughs, then holds the cup out again. Brewer all the way, Duren insists.","heroes":["h3","h7"],"parties":["p7"],"loc":"whitepeak","skill":"brewer","wx":"snow"},{"id":"e3066","day":81,"season":3,"sday":21,"kind":"delve","imp":1,"text":"The Oath of Frosthold descends into Frostspire, mostly unexplored (32%).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","wx":"snow"},{"id":"e3069","day":81,"season":3,"sday":21,"kind":"fight","imp":3,"text":"In the frozen ballroom on the second floor of Frostspire, the Oath of Frosthold is routed by 3 Ice Wraiths. Vex was first out the door and would like that kept quiet. Injured: Vex (sprained ankle).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","fight":"f174","foes":["ice_wraith","ice_wraith","ice_wraith"],"where":"in the frozen ballroom on the second floor of Frostspire","won":false,"close":true,"shape":"place","reworded":15,"wx":"snow"},{"id":"e3070","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"It's the second floor of Frostspire today, and The Oath of Frosthold works through it at a steady pace: two rooms (the meltwater seep, the frozen ballroom).","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3071","day":81,"season":3,"sday":21,"kind":"delve_done","imp":1,"text":"The Oath of Frosthold climbs out after a day with something unfriendly close behind and no wish to discuss it. They reached the second floor, took 1 room off the map's blank side and split 19 silver on the way up.","heroes":["h3","h7"],"parties":["p7"],"loc":"frostspire","days":1,"bottom":false,"rooms":[],"gold":19,"out":"Driven out","turn":"routed","wx":"snow"},{"id":"e3091","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 17 sales, 870 silver changing hands. Biggest haul: Duren, 103 silver in Frosthold. Back up from the deep: Red Hammers (3 days in Thornmere Ruins), Gilded Wall (2 days in Emberdeep), The Oath of Frosthold (1 day in Frostspire).","heroes":["h3","h13","h9"],"parties":["p1","p6","p7"]},{"id":"e3094","day":82,"season":3,"sday":22,"kind":"night","imp":2,"text":"Someone leaves a scrap of map by The Oath of Frosthold's fire in Whitepeak Pass in the night. It shows a door in Goblin Camp that isn't on any other map.","heroes":["h3","h7"],"parties":["p7"],"loc":"whitepeak"},{"id":"e3127","day":82,"season":3,"sday":22,"kind":"argument","imp":2,"text":"Duren says one thing too many about Duren's snoring. Vex says two.","heroes":["h3","h7"],"parties":["p7"]},{"id":"e3160","day":83,"season":3,"sday":23,"kind":"campfire","imp":1,"text":"Duren mends Vex's bootlace with a bit of string and a great deal of confidence.","heroes":["h3","h7"],"parties":["p7"],"loc":"frosthold","wx":"storm"},{"id":"e3231","day":85,"season":3,"sday":25,"kind":"talent","imp":2,"text":"Vex trades a Veldrock baker a sourdough starter for a sack of flour. The baker's eyes light up.","heroes":["h7"],"parties":["p7"],"loc":"veldrock","skill":"trail_baker"},{"id":"e3232","day":85,"season":3,"sday":25,"kind":"ability","imp":2,"text":"Word gets round Veldrock that Vex is playing tonight. They're standing on the tables by nine. 55 silver in tips, and Duren gets free drinks for being with the band.","heroes":["h7","h3"],"parties":["p7"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e3239","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Duren and Vex spend an evening at The Pickaxe & Pint trying to whistle through a blade of grass. Only Vex manages.","heroes":["h3","h7"],"parties":["p7"],"loc":"veldrock"},{"id":"e3241","day":85,"season":3,"sday":25,"kind":"goal_progress","imp":2,"text":"The Oath of Frosthold is getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h3","h7"],"parties":["p7"]},{"id":"e3251","day":86,"season":3,"sday":26,"kind":"road","imp":3,"text":"Sir Aldous Puddle proudly shows Duren the tally on the bridge board. Duren is surprised to find it very close.","heroes":["h3","h7"],"parties":["p7"],"road":"redcrag~veldrock","traveller":"aldous","road_rec":"r694"},{"id":"e3252","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Vex carries Duren's pack the last mile back to camp and says it was no trouble. It was some trouble. Heavy Lifter, the way the drill-yards teach it.","heroes":["h7","h3"],"parties":["p7"],"loc":"redcrag","skill":"heavy_lifter"},{"id":"e3285","day":87,"season":3,"sday":27,"kind":"fight","imp":1,"text":"With Duren hitting hardest, the Oath of Frosthold beats 3 Kobolds in Redcrag Hills. Duren cleared two kobolds with a single Steam Burst. Loot: 12 silver each, 2 ore, a kobold firepepper.","heroes":["h3","h7"],"parties":["p7"],"loc":"redcrag","fight":"f188","foes":["kobold","kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"hero","reworded":-28},{"id":"e3329","day":88,"season":3,"sday":28,"kind":"talent","imp":2,"text":"Duren has no eyebrows again. He says it was worth it, and won't explain.","heroes":["h3"],"parties":["p7"],"loc":"redcrag","skill":"burn_it_and_see"},{"id":"e3391","day":89,"season":3,"sday":29,"kind":"campfire","imp":1,"text":"Duren slips Clementine a sausage under the table. Vex sees, and decides Duren is all right.","heroes":["h7","h3"],"parties":["p7"],"loc":"redcrag","wx":"fog"},{"id":"e3415","day":90,"season":3,"sday":30,"kind":"ability","imp":2,"text":"The Veldrock tavern is full before Vex has tuned up, and nobody leaves before the third encore. 46 silver in the hat, and the crew sings along from the front table.","heroes":["h7"],"parties":["p7"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"snow"},{"id":"e3437","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Oath of Frosthold came up short: see the world: 6 different places before the season ends (5 of 6 places).","heroes":["h3","h7"],"parties":["p7"]},{"id":"e3450","day":90,"season":3,"sday":30,"kind":"vow_broken","imp":3,"text":"VOW BROKEN. Red Hammers, The Oath of Frosthold, Ottoline and Rook swore to die rich, and the age ends with the purse short. Comfortable, at best.","heroes":["h14","h15"],"parties":["p1","p7"]}],"roles":{"h7":"Talker","h3":"Leader · Spellcaster"},"quest":{"what":"Head home","where":"Frosthold","why":"heading home to Frosthold","floor":null,"floors":null},"tactics":{"front":[],"back":["h3","h7"],"plan":"Duren casts from behind; Vex picks off whatever gets close.","traits":{"boldness":-0.02,"risk":-0.72,"greed":-0.19,"sociability":0.07,"honor":0.12,"curiosity":0.35,"temper":-0.33,"loyalty":-0.36},"mix":"1 caster, 1 talker","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["patient","mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h3","id":"firebolt","name":"Firebolt","desc":"The classic.","tags":["fire"],"rank":1,"uses":13},{"hero":"h3","id":"steam_burst","name":"Steam Burst","desc":"Fire meets ice. Everyone gets a facial.","tags":["fire","ice"],"rank":2,"uses":7},{"hero":"h3","id":"frost_shard","name":"Frost Shard","desc":"A spike of winter.","tags":["ice"],"rank":1,"uses":7},{"hero":"h3","id":"flame_jet","name":"Flame Jet","desc":"Two quick gouts from the fingertips.","tags":["fire"],"rank":1,"uses":6},{"hero":"h3","id":"immolate","name":"Immolate","desc":"Sets one target on fire, thoroughly.","tags":["fire"],"rank":1,"uses":3},{"hero":"h3","id":"solar_flare","name":"Solar Flare","desc":"Brings a bit of noon into the cave.","tags":["fire"],"rank":1,"uses":1}]},{"label":"Defence","skills":[{"hero":"h7","id":"tailwind","name":"Tailwind","desc":"The wind is suddenly on everyone's side.","tags":["storm","travel"],"rank":2,"uses":9},{"hero":"h7","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":1,"uses":8},{"hero":"h7","id":"saga_of_fury","name":"Saga of Fury","desc":"Three verses, each angrier. Nobody waits for the fourth.","tags":["rage","music"],"rank":1,"uses":2},{"hero":"h7","id":"the_spread","name":"The Spread","desc":"Lays out three cards and tells the crew which way the fight goes. They believe it.","tags":["fate"],"rank":1,"uses":1}]},{"label":"Tricks","skills":[{"hero":"h7","id":"marching_song","name":"Marching Song","desc":"Everybody steps off on the same foot.","tags":["music","travel"],"rank":2,"uses":9},{"hero":"h7","id":"off_key_note","name":"Off-Key Note","desc":"Hits a note so wrong the goblins reconsider their careers.","tags":["music"],"rank":1,"uses":8},{"hero":"h3","id":"phoenix_heart","name":"Phoenix Heart","desc":"Rises from the ashes, slightly singed.","tags":["fire"],"rank":3,"uses":0}]},{"label":"Always on","skills":[{"hero":"h3","id":"thick_skin","name":"Thick Skin","desc":"Bruises, doesn't break.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"know_thy_enemy","name":"Know Thy Enemy","desc":"Read the bestiary. Twice.","tags":["lore"],"rank":1,"uses":0},{"hero":"h7","id":"shoulder_to_shoulder","name":"Shoulder to Shoulder","desc":"Stands close enough to share a shield.","tags":["command"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h3","id":"study","name":"Studious","desc":"Reads everything, learns faster.","tags":["lore"],"rank":1,"uses":0},{"hero":"h3","id":"smelters_touch","name":"Smelter's Touch","desc":"Heats metal by hand. Smiths pay for it.","tags":["fire"],"rank":1,"uses":0},{"hero":"h3","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"fire_eater","name":"Fire Eater","desc":"Eats fire. Never orders hot soup.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"ember_bed","name":"Ember Bed","desc":"Sleeps on warm stones. Bruises are gone by breakfast.","tags":["fire"],"rank":1,"uses":0},{"hero":"h3","id":"bonfire_night","name":"Bonfire Night","desc":"Lights a bonfire on the green. Half the town turns up; one stays.","tags":["fire"],"rank":2,"uses":0},{"hero":"h7","id":"heavy_lifter","name":"Heavy Lifter","desc":"Carries the chest. And the person sitting on the chest.","tags":["travel"],"rank":2,"uses":0},{"hero":"h7","id":"ghost_stories","name":"Ghost Stories","desc":"Turns a dark night into a darker one, deliciously.","tags":["lore","death"],"rank":1,"uses":0},{"hero":"h7","id":"snowcraft","name":"Snowcraft","desc":"Knows snow: which holds, which slides, which bites.","tags":["ice","travel"],"rank":1,"uses":0},{"hero":"h7","id":"peacemaker","name":"Peacemaker","desc":"Stops the argument before it gets to the swords.","tags":["command","holy"],"rank":1,"uses":0},{"hero":"h7","id":"songwriter","name":"Songwriter","desc":"Every fight becomes a verse, eventually.","tags":["music"],"rank":3,"uses":0},{"hero":"h7","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h3","dmg":1235,"healed":0,"taken":90,"kills":6,"row":"back"},{"hero":"h7","dmg":182,"healed":43,"taken":320,"kills":2,"row":"back"}],"ground":{"name":"Frostspire","fights":4}},"trophies":[{"boss":"Old Grizzlemaw's Widow","monster":"cave_bear","place":"The Wolf Den","day":48,"season":2,"fight":"f106"}]};